	@Test
	void certifiedPartitionCapBoundsExpectedOwnerWorkWithoutClaimingExactWork() throws Exception {
		Measured measured = execute(2, false, true);
		assertThat(measured.requestedPartitions()).isEqualTo(2);
		assertThat(measured.returnedPartitions()).isEqualTo(2);
		assertThat(measured.workerKeys()).isEqualTo(4L);
		assertThat(measured.outputs()).isEqualTo(2);
		assertThat(measured.features().expected(Feature.OUTPUT_MATERIALIZATION)).isEqualTo(2D);
		double measuredEffectiveWork = measured.privateUpdates() / measured.speedup() + measured.workerKeys();
		assertThat(measuredEffectiveWork).as("preserved physical evidence from the original 64-versus-36 red")
				.isEqualTo(36D);
		double conservativeOwnerKeys = 2D * Math.max(2L,
				LmdbNativeParallelKernelRows.rootWindowCount(Long.MAX_VALUE, 2));
		assertThat(conservativeOwnerKeys).as("two estimated keys across at most eight possible adjacency windows")
				.isEqualTo(16D);
		assertThat(measured.features().expected(Feature.DISTINCT_UPDATE))
				.as("conservative 48 is distinct from measured 36; the quote also permits successful adjacency binding")
				.isCloseTo(measured.privateUpdates() / measured.speedup() + conservativeOwnerKeys, within(1e-10));
		assertThat(measured.features().high(Feature.DISTINCT_UPDATE))
				.isGreaterThanOrEqualTo(measured.privateUpdates() / measured.speedup() + 32D);
	}

