			assertThat(scan).isNotNull();
			assertThat(scan.kernel.resumable).isTrue();
			assertThat(LmdbNativeKernelPartitions.partitionableRootAdjacency(scan.kernel.pipeline)).isNegative();
			assertThat(LmdbNativeKernelPartitions.partitionableRootScan(scan.kernel.pipeline)).isNotNegative();
			assertThat(scan.distinctRowInput).isNotNull();
			assertThat(scan.distinctRowInput.spine()).hasSize(2);
			assertThat(scan.distinctRowInput.witnesses()).isEmpty();
			assertThat(fixture.source.adjacencyKeyDomainCardinality(ScanSource.P1, true)).isEmpty();
