			// Only the selected IR actually opens ranges and worker sources. The direct scan control has one plan.
			assertThat(fixture.source.plans.get()).isEqualTo(2);
			assertThat(fixture.source.opened.get()).isEqualTo(2);
			assertThat(fixture.source.closed.get()).isEqualTo(2);
			assertThat(fixture.source.partitionOpens.get()).isEqualTo(returnedPartitions);
